import{_ as e,o,c as r,ag as d}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"Builder Bake-off Scorecard","description":"","frontmatter":{"source":"weeks/06-spec-to-app/bake-off-scorecard.md"},"headers":[],"relativePath":"weeks/06-spec-to-app/bake-off-scorecard.md","filePath":"weeks/06-spec-to-app/bake-off-scorecard.md"}'),a={name:"weeks/06-spec-to-app/bake-off-scorecard.md"};function s(i,t,n,l,c,h){return o(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="builder-bake-off-scorecard" tabindex="-1">Builder Bake-off Scorecard <a class="header-anchor" href="#builder-bake-off-scorecard" aria-label="Permalink to &quot;Builder Bake-off Scorecard&quot;">​</a></h1><blockquote><p>Use this in <a href="./lab.html#part-1--builder-bake-off-jigsaw-45-min">lab Part 1</a>, in week 6 Studio A. Copy its text into your notes for the studio, then into your Project 1 repository as <code>docs/bake-off-scorecard.md</code> (sections 1–5 only) for homework. <strong>Section 6, the Verdict, goes on Canvas</strong>, not in your repository.</p><p><strong>Score by your acceptance criteria, not by how pretty it looks.</strong> A beautiful app that fails AC3 fails AC3.</p></blockquote><p><strong>GitHub username:</strong> [your username] · <strong>Project:</strong> [project name] · <strong>Date:</strong> [date] <strong>My builder:</strong> [builder A or B, and its name] · <strong>Spec used:</strong> [for example &quot;SPEC.md after the Goldfish test&quot;, or a link to the commit]</p><h2 id="the-rules" tabindex="-1">The rules <a class="header-anchor" href="#the-rules" aria-label="Permalink to &quot;The rules&quot;">​</a></h2><ol><li><strong>One builder each.</strong> You test the builder you were given, on your own spec. Your partner tests the other builder on theirs. You compare in step 6.</li><li><strong>Same input as everyone:</strong> the lab&#39;s framing prompt, then your whole <code>SPEC.md</code>.</li><li><strong>Time box:</strong> 20 minutes, from pasting the spec to finishing sections 1–4.</li><li><strong>Credit budget:</strong> at most <strong>3 prompts</strong>: the spec, then up to 2 fix prompts that each name a failing criterion (for example &quot;AC5 fails: …&quot;).</li><li><strong>No personal data</strong> in anything you paste. Some free tiers let human reviewers read what you type (<a href="./../../TOOLS.html">Tool Handout</a>).</li></ol><p>Key for results: ✅ passes · <strong>X</strong> fails · <strong>~</strong> partly · <strong>n/t</strong> not tested (say why in Notes)</p><h2 id="1-acceptance-criteria" tabindex="-1">1. Acceptance criteria <a class="header-anchor" href="#1-acceptance-criteria" aria-label="Permalink to &quot;1. Acceptance criteria&quot;">​</a></h2><p>List every criterion from your <code>SPEC.md</code>. Test each one by hand in the builder&#39;s preview. Fill in the &quot;My plain version&quot; column for homework, on your live site.</p><table tabindex="0"><thead><tr><th>AC</th><th>Priority</th><th>My builder</th><th>My plain version</th><th>Notes (what exactly happened?)</th></tr></thead><tbody><tr><td>AC1</td><td></td><td></td><td></td><td></td></tr><tr><td>AC2</td><td></td><td></td><td></td><td></td></tr><tr><td>AC3</td><td></td><td></td><td></td><td></td></tr><tr><td>AC4</td><td></td><td></td><td></td><td></td></tr><tr><td>AC5</td><td></td><td></td><td></td><td></td></tr><tr><td>AC6</td><td></td><td></td><td></td><td></td></tr><tr><td>AC7</td><td></td><td></td><td></td><td></td></tr><tr><td>AC8</td><td></td><td></td><td></td><td></td></tr><tr><td><strong>MUST criteria passed</strong></td><td></td><td>__ / __</td><td>__ / __</td><td></td></tr><tr><td><strong>All criteria passed</strong></td><td></td><td>__ / __</td><td>__ / __</td><td></td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Test the &quot;reload&quot; criterion with care. Some builder previews run inside a frame that may not keep saved data the way a real website does. If reloading behaves oddly, write what you saw in Notes and mark it <strong>n/t</strong>. You&#39;ll test it properly on your own site.</p></div><h2 id="2-under-the-hood" tabindex="-1">2. Under the hood <a class="header-anchor" href="#2-under-the-hood" aria-label="Permalink to &quot;2. Under the hood&quot;">​</a></h2><p>Open the builder&#39;s code or files view. You don&#39;t need to understand the code. You&#39;re looking for clues.</p><table tabindex="0"><thead><tr><th>Question</th><th>My builder</th></tr></thead><tbody><tr><td>Language and framework. Clues: files ending <code>.tsx</code> or <code>.jsx</code> usually mean React; <code>.ts</code> means TypeScript; a <code>package.json</code> lists the libraries</td><td></td></tr><tr><td>Is there a build step? (Does <code>package.json</code> have a <code>&quot;build&quot;</code> script?)</td><td></td></tr><tr><td>Did it add a server, a database or a login? Which?</td><td></td></tr><tr><td>Roughly how many files did it create?</td><td></td></tr><tr><td>Where is your data saved? (Search the code for <code>localStorage</code>, <code>firebase</code>, <code>supabase</code> or <code>database</code>)</td><td></td></tr><tr><td>Did it respect your <strong>Constraints</strong> section? What did it ignore?</td><td></td></tr><tr><td>Did it build anything from your <strong>Out of scope</strong> list?</td><td></td></tr><tr><td>Did it write any automated tests? Where would your logic plan&#39;s rules live in its code?</td><td></td></tr></tbody></table><h2 id="3-cost-and-lock-in" tabindex="-1">3. Cost and lock-in <a class="header-anchor" href="#3-cost-and-lock-in" aria-label="Permalink to &quot;3. Cost and lock-in&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Question</th><th>My builder</th></tr></thead><tbody><tr><td>Usage shown on the dashboard <strong>before</strong> you started</td><td></td></tr><tr><td>Usage <strong>after</strong> you finished</td><td></td></tr><tr><td>Prompts used (max 3) and minutes spent</td><td></td></tr><tr><td>Can you export the code to GitHub? What is the button called?</td><td></td></tr><tr><td>Can you download it as a ZIP file?</td><td></td></tr><tr><td>To publish it on the web, what would you need (an account, a paid plan, a billing account)?</td><td></td></tr><tr><td>If this builder shut down tomorrow, what would you lose?</td><td></td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Menus move. If you can&#39;t find the usage page or the export button in two minutes, ask the builder itself (&quot;Where can I see my usage? How do I export this project to GitHub?&quot;) and note its answer.</p></div><h2 id="4-what-surprised-you" tabindex="-1">4. What surprised you? <a class="header-anchor" href="#4-what-surprised-you" aria-label="Permalink to &quot;4. What surprised you?&quot;">​</a></h2><ul><li></li></ul><h2 id="5-my-partners-builder-and-the-class-board" tabindex="-1">5. My partner&#39;s builder, and the class board <a class="header-anchor" href="#5-my-partners-builder-and-the-class-board" aria-label="Permalink to &quot;5. My partner&#39;s builder, and the class board&quot;">​</a></h2><p>Copy your partner&#39;s totals from their scorecard. (Their results come from <strong>their</strong> spec, so compare the share of MUSTs passed, not the raw numbers.)</p><table tabindex="0"><thead><tr><th>Question</th><th>My builder</th><th>My partner&#39;s builder</th></tr></thead><tbody><tr><td>Builder name</td><td></td><td></td></tr><tr><td>MUST criteria passed</td><td>__ / __</td><td>__ / __</td></tr><tr><td>Framework and build step</td><td></td><td></td></tr><tr><td>Added a login, database or out-of-scope feature?</td><td></td><td></td></tr><tr><td>Export to GitHub?</td><td></td><td></td></tr><tr><td>Could either of us explain its code line by line?</td><td></td><td></td></tr></tbody></table><p>Add one line to the class results board (your instructor shares it):</p><p><code>[builder] · MUST passed __/__ · tech: [framework] · added login/database: yes/no · export to GitHub: yes/no</code></p><h2 id="6-verdict-on-canvas" tabindex="-1">6. Verdict (on Canvas) <a class="header-anchor" href="#6-verdict-on-canvas" aria-label="Permalink to &quot;6. Verdict (on Canvas)&quot;">​</a></h2><blockquote><p>🔴 <strong>AI off.</strong> Write your answers on Canvas, not in this file. They are your week 6 reflection (150–300 words), graded on specifics.</p></blockquote><ol><li>Which builder passed a bigger share of its MUST criteria, yours or your partner&#39;s? Was it the one that looked better at first sight?</li><li>Pick one criterion that failed. Was the builder wrong, or was your criterion unclear? Quote the words you changed (or will change) in <code>SPEC.md</code>.</li><li>Which version could you explain line by line to a classmate: your builder&#39;s, your partner&#39;s, or your plain version? Why does that matter for week 7, when you debug with the AI switched off?</li><li>How much of your free allowance did this use? Would you pay for this tool? For what kind of project?</li></ol>',26)])])}const b=e(a,[["render",s]]);export{p as __pageData,b as default};
